def c(f,o,v=None):return {'field':f,'operator':o,**({'value':v} if v is not None else {})}
def allc(*a):return {'all':list(a)}
def anyc(*a):return {'any':list(a)}
def eq(f,v=True):return c(f,'==',v)
rules=[]
def rule(id,cond,act,msg,page,url=src,extra=None):
 a={'type':act,'components':['brigatinib'],'message':msg,'recommendation':msg}
 if act not in ['permanently_discontinue','contraindicated']:a['dose_calculation']='specialist_review'
 if extra:a.update(extra)
 rules.append({'id':id,'priority':10 if act in ['contraindicated','permanently_discontinue'] else 8,'when':cond,'action':a,'source':{'document':'NCCP 00562 v4' if url==src else 'EMA Alunbrig SmPC (supplement)','url':url,'page':str(page)},'explanation':msg})
rule('ECOG_OUTSIDE_USUAL_RANGE',c('ecog','>',2),'consultant_review','ECOG exceeds NCCP eligibility 0–2; Consultant review of treatment suitability.','1')
for id,f,msg,page in [('HYPERSENSITIVITY','hypersensitivity','Known or suspected hypersensitivity to brigatinib or an excipient: do not administer.',1),('BASELINE_ILD_EXCLUSION','clinically_significant_ild_history','NCCP excludes clinically significant pre-existing ILD or drug-related pneumonitis; review before treatment.',1),('UNCONTROLLED_CARDIOVASCULAR','uncontrolled_cardiovascular_disease','NCCP excludes clinically significant uncontrolled cardiovascular disease, including uncontrolled hypertension or significant bradycardia.',2),('LACTOSE_DISORDER','lactose_related_hereditary_disorder','This lactose-containing product should not be taken in the listed hereditary disorders.',7)]:rule(id,eq(f),'contraindicated',msg,page)
rule('PREGNANCY_REVIEW',eq('pregnancy'),'withhold','Pregnancy requires urgent Consultant necessity and foetal-risk review; SmPC says do not use unless the maternal clinical condition requires treatment. This is not a universal absolute contraindication.',11,smpc)
rule('BREASTFEEDING_REVIEW',eq('breastfeeding'),'withhold','Breastfeeding must stop during brigatinib; obtain the prescriber’s agreed feeding/treatment plan before proceeding.',11,smpc)
for f,id in [('alk_positive_validated','ALK_CONFIRMATION'),('advanced_nsclc_confirmed','ADVANCED_NSCLC_SCOPE')]:rule(id,eq(f,False),'consultant_review','NCCP requires validated ALK-positive advanced NSCLC; resolve the eligibility finding before prescribing.',1)
rule('PRIOR_TREATMENT_SCOPE',anyc(eq('prior_alk_inhibitor','other'),allc(eq('indication_id','00562a'),eq('prior_alk_inhibitor','none')),allc(eq('indication_id','00562b'),eq('prior_alk_inhibitor','crizotinib'))),'consultant_review','00562a is after crizotinib; 00562b is ALK-inhibitor naïve. Other ALK exposure or a discordant selection needs a separate indication/MDT decision, not automatic transfer of trial results.',1)
rule('RESTART_14_DAYS',allc(c('interruption_days','>=',14),eq('interruption_reason','other')),'consultant_review','For a non-adverse-reaction interruption of at least 14 days, source restart is 90 mg once daily for seven days before the previously tolerated dose. Confirm prior tolerated dose, renal/hepatic limitations, interactions and early lung events; do not raise a tolerated 60 mg dose automatically.',2)
rule('RESTART_REASON_MISSING',allc(c('interruption_days','>=',14),c('interruption_reason','missing')),'consultant_review','An interruption of at least 14 days requires the reason and prior dose before choosing a restart. The standard re-lead-in applies only to reasons other than adverse reactions.',2)
rule('ADVERSE_REACTION_RESTART',allc(eq('treatment_phase','restart'),eq('interruption_reason','adverse_reaction')),'consultant_review','Use the event-specific recovery, recurrence and reduction pathway for an adverse-reaction restart; do not automatically reuse the non-adverse-reaction 90 mg lead-in.',2)
rule('EARLY_PNEUMONITIS_NO_ESCALATION',eq('prior_early_pneumonitis'),'consultant_review','Prior ILD/pneumonitis in the first seven days prevents routine escalation to 180 mg. Confirm the recorded grade, recurrence and tolerated dose with the Consultant.',3)
rule('UNABLE_TOLERATE_60',eq('unable_to_tolerate_60mg'),'permanently_discontinue','Permanently discontinue when 60 mg once daily cannot be tolerated.',2)
rule('RECENT_CRIZOTINIB',c('days_since_last_crizotinib','<',7),'consultant_review','An interval under seven days from crizotinib is associated with more early pulmonary events; review initiation and intensified symptom observation. This is a risk flag, not an invented mandatory washout.',6)
# Haematology keeps the printed AND and flags the unsupported isolated/mixed situations.
