haem3=allc(c('anc_x10e9_l','between_inclusive',[.5,1]),c('platelets_x10e9_l','between_inclusive',[25,50]));haem4=allc(c('anc_x10e9_l','<',.5),c('platelets_x10e9_l','<',25))
rule('HAEMATOLOGY_G3_BOTH',haem3,'withhold','Both printed intermediate count bands met: withhold to baseline. First occurrence resumes the same dose; recurrence requires lower level or permanent discontinuation by Consultant choice.',3)
