rule('RENAL_DIALYSIS_REVIEW',eq('targeted_renal_band','dialysis'),'consultant_review','Dialysis is not a separately defined dosing population in NCCP Table 3; obtain oncology pharmacy/Consultant review rather than assign the <30 mL/min schedule automatically.',3)
