rule('OF590_00562_BRIG_CHILD_C',eq('targeted_hepatic_band','C'),'dose_reduce','Severe baseline hepatic impairment (Child–Pugh C): reference starting schedule 60 mg daily for seven days, then 120 mg daily. Distinguish baseline impairment from treatment hepatotoxicity.',3)
rule('COMBINED_LIMITATIONS',anyc(allc(renal,eq('targeted_hepatic_band','C')),allc(anyc(renal,eq('targeted_hepatic_band','C')),eq('strong_cyp3a_inhibitor'))),'consultant_review','Multiple renal/hepatic/interaction dose limitations coexist. Source gives separate schedules, not a combined formula; Consultant and pharmacy must agree the dose. Do not multiply reductions.', '3,7')
