rule('PNEUMONITIS_HOLD',c('pneumonitis_grade','in',[1,2]),'withhold','Grade 1–2 treatment-emergent ILD/pneumonitis: hold to baseline. Confirm timing and recurrence before restart; early events must not be escalated to 180 mg.',3)
for g in [1,2]:
 for early in [True,False]:
  msg=('Same dose level' if g==1 else 'Next lower dose level')+' only after recovery to baseline and Consultant review.'+(' Do not escalate to 180 mg after an event within the first seven days.' if early else ' This event occurred after the first seven days.')
