rule('BP_GRADE_CONTEXT',anyc(c('systolic_bp_mmhg','>=',160),c('diastolic_bp_mmhg','>=',100)),'consultant_review','This blood pressure meets the numeric severe-hypertension signal. Confirm clinical grade, symptoms and treatment-intensification criteria; numeric BP alone does not supply full CTCAE v4 context.',4,smpc)
rule('QTC_SOURCE_CAUTION',anyc(allc(eq('qtc_source_sex','male'),c('qtcf_ms','>',450)),allc(eq('qtc_source_sex','female'),c('qtcf_ms','>',470)),allc(c('qtc_source_sex','missing'),c('qtcf_ms','>',450))),'consultant_review','NCCP cautions at QTcF >450 ms in males or >470 ms in females. Review ECG, medicines and electrolytes; source does not provide an automatic ≥500 ms brigatinib withholding threshold.',1)
