rule('BRADYCARDIA_SYMPTOMATIC_ADJUSTED',allc(eq('bradycardia_symptomatic'),eq('bradycardia_life_threatening',False),eq('bradycardia_contributor','adjusted')),'withhold','After the contributing medicine is stopped/adjusted and symptoms or heart rate recover, same-dose resumption may be used for non-life-threatening symptomatic bradycardia.',4)
rule('BRADYCARDIA_SYMPTOMATIC_REDUCE',allc(eq('bradycardia_symptomatic'),eq('bradycardia_life_threatening',False),c('bradycardia_contributor','in',['none','not_adjusted'])),'withhold_then_reduce','No addressed contributor to symptomatic bradycardia: after recovery, resume at next lower dose level with Consultant review.',4)
rule('BRADYCARDIA_LIFE_ADJUSTED',allc(eq('bradycardia_life_threatening'),eq('bradycardia_contributor','adjusted'),eq('bradycardia_recurrent',False)),'withhold_then_reduce','First life-threatening bradycardia with contributing medicine stopped/adjusted: after recovery, next lower dose level with frequent monitoring.',4)
rule('BRADYCARDIA_STOP',anyc(eq('bradycardia_recurrent'),allc(eq('bradycardia_life_threatening'),eq('bradycardia_contributor','none'))),'permanently_discontinue','Recurrent life-threatening bradycardia, or life-threatening bradycardia without an identified contributing medicine, requires permanent discontinuation.',4)
