rule('HEPATOTOXICITY_HOLD',allc(c('alt_ast_uln_multiple','>',5),c('bilirubin_uln_multiple','<=',2)),'withhold_then_reduce','ALT or AST >5 × ULN with bilirubin ≤2 × ULN: hold to baseline or ≤3 × ULN, then next lower dose level.',5)
rule('HEPATOTOXICITY_MISSING_BILI',allc(c('alt_ast_uln_multiple','>',5),c('bilirubin_uln_multiple','missing')),'withhold','Marked transaminase elevation with bilirubin unknown: withhold pending complete liver assessment; do not infer a restart dose or permanent stop from the incomplete pattern.',5)
rule('HEPATOTOXICITY_COMBINED_HOLD',allc(c('alt_ast_uln_multiple','>',3),c('bilirubin_uln_multiple','>',2)),'withhold','Concurrent ALT/AST >3 × ULN and bilirubin >2 × ULN needs urgent cause assessment. Hold while cholestasis/haemolysis and treatment attribution are reviewed; confirmed absence plus clinical treatment attribution selects the source permanent-stop row.',5)
rule('HEPATOTOXICITY_STOP',allc(c('alt_ast_uln_multiple','>',3),c('bilirubin_uln_multiple','>',2),eq('cholestasis_or_haemolysis',False),eq('liver_injury_treatment_related')),'permanently_discontinue','Concurrent ALT/AST >3 × ULN and total bilirubin >2 × ULN without cholestasis or haemolysis: permanently discontinue for the treatment-related hepatotoxicity pattern.',5)
rule('GLUCOSE_OPTIMISE',c('fasting_glucose_mmol_l','>',13.9),'consultant_review','Fasting glucose >13.9 mmol/L reaches the source grade ≥3 threshold; initiate/optimise glucose treatment and assess whether adequate control is achievable.',5)
rule('GLUCOSE_UNCONTROLLED_HOLD',eq('glucose_uncontrolled_despite_optimal_management'),'withhold','Adequate glucose control has not been achieved despite optimal management: hold until controlled. After recovery, Consultant choice is next lower dose or permanent discontinuation; no automatic restart.', '5,7')
rule('VISUAL_G2_3',c('visual_disturbance_grade','in',[2,3]),'withhold_then_reduce','Grade 2/3 visual disturbance: hold to grade 1 or baseline, arrange ophthalmic assessment as appropriate, then next lower level.',5)
rule('VISUAL_G4',eq('visual_disturbance_grade',4),'permanently_discontinue','Grade 4 visual disturbance requires permanent discontinuation.',5)
other3=anyc(*[eq(f,3) for f in ['diarrhoea_grade','rash_grade','other_toxicity_grade']]);other4=anyc(*[eq(f,4) for f in ['diarrhoea_grade','rash_grade','other_toxicity_grade']])
rule('OTHER_G3_HOLD',other3,'withhold','Other grade 3 toxicity (including diarrhoea or rash without a separate specific pathway): hold to baseline. First event resumes same dose; recurrence requires next lower dose or permanent discontinuation.',5)
rule('OTHER_G4_HOLD',other4,'withhold_then_reduce','Other grade 4 toxicity: hold to baseline, then next lower dose level. If recurrent, Consultant chooses lower dose or permanent discontinuation.',5)
rule('OTHER_RECURRENCE',allc(anyc(other3,other4),eq('other_event_recurrent')),'withhold','Recurrent other grade 3/4 toxicity: hold to baseline, then Consultant choice of next lower dose level or permanent discontinuation.',5)
rule('STRONG_CYP3A_INHIBITOR',eq('strong_cyp3a_inhibitor'),'consultant_review','Avoid strong CYP3A inhibitors. If unavoidable, source reference changes are 180 to 90 mg daily or 90 to 60 mg daily; after stopping, return only to the previously tolerated dose under pharmacy review. No published automatic conversion for every reduced-dose/organ-function combination.',7)
rule('MODERATE_CYP3A_CONFLICT',eq('moderate_cyp3a_inhibitor'),'consultant_review','Source conflict: NCCP v4 says avoid moderate CYP3A inhibitors; current SmPC 4.5 permits no routine dose adjustment with close monitoring. Resolve with Consultant/pharmacy; do not silently substitute either policy.',7)
rule('STRONG_CYP3A_INDUCER',eq('strong_cyp3a_inducer'),'consultant_review','Current SmPC advises avoiding strong CYP3A inducers (including St John’s wort). Review an alternative; do not invent a compensatory brigatinib dose.',10,smpc)
rule('MODERATE_CYP3A_INDUCER',eq('moderate_cyp3a_inducer'),'consultant_review','Current SmPC advises avoiding moderate CYP3A inducers. If unavoidable, specialist-only 30 mg increments after seven days at the current dose as tolerated, up to twice the pre-inducer tolerated dose; revert after stopping the inducer. This is not an automatic calculator or routine escalation.', '9–10',smpc)
rule('CYP3A_SUBSTRATE',eq('narrow_index_cyp3a_substrate'),'consultant_review','Avoid narrow-therapeutic-index CYP3A substrates because brigatinib can reduce their exposure/effectiveness; pharmacy review is needed.', '10–11',smpc)
rule('TRANSPORTER_SUBSTRATE',eq('narrow_index_transporter_substrate'),'consultant_review','Brigatinib may increase transporter-substrate exposure; closely monitor narrow-index P-gp/BCRP/OCT1/MATE substrates and obtain pharmacy advice.',11,smpc)
rule('GRAPEFRUIT',eq('grapefruit_use'),'consultant_review','Avoid grapefruit and grapefruit juice; review exposure and other interacting medicines with pharmacy.',1)
rule('MISSED_VOMITED_DOSE',eq('missed_or_vomited_dose'),'consultant_review','Do not take an extra dose after a missed or vomited dose. Take the next dose at the scheduled time; persistent vomiting or inability to retain fluids/medicine needs clinical advice.',1)
p['rule_engine']['rules']=rules;p['rule_engine']['missing_data_policy']='Generate partial assessment and missing-context findings; missing inputs are not normal. Do not authorise treatment.'
p['monitoring']={'baseline':['Validated ALK testing; FBC, renal/liver profile; pulmonary function test; ECG and blood pressure; fasting glucose, CPK and amylase and/or lipase.'],'regular':['FBC and renal profile monthly.','ECG and blood pressure every two weeks during the first treatment period, then monthly or as indicated.','Liver profile every two weeks for first three months, then as clinically indicated.','Clinical pulmonary review on days 8 and 15, then monthly or as clinically indicated; do not delay reporting early symptoms until these reviews.','Fasting glucose, CPK and amylase and/or lipase monthly.'],'disease':['Consultant-directed disease assessment; no fixed scan interval invented.']}
p['supportive_care'].update(emetogenic_risk='oral_minimal_low',antiemetic_script_id='nccp-oral-minimal-low',premedication='Not routinely required by NCCP.',other_support='No NCCP-specific routine prophylaxis; prescribe symptom support individually.',oral_administration='Swallow whole with water, with or without food; avoid grapefruit. Do not replace a missed/vomited dose.')
p['eligibility']=['Adults with validated ALK-positive advanced NSCLC, matching 00562a or 00562b.','ECOG 0–2 and adequate organ function; Consultant Medical Oncologist initiation.'];p['exclusions']=['Known or suspected hypersensitivity.','Clinically significant pre-existing ILD or drug-related pneumonitis.','Clinically significant uncontrolled cardiovascular disease, hypertension or bradycardia.']
